const baseUrl = 'https://awash-portal.vercel.app/';

// Replace these test records with your authorized test users/data.
// Keep real credentials in n8n credentials or environment variables in production.
const adminUsers = [
  { username: 'admin@awashinsurance.com', password: 'REPLACE_WITH_TEST_PASSWORD' }
];

const recordsToCreate = [
  {
    firstName: 'Test',
    lastName: 'Customer',
    email: 'test.customer.001@example.com',
    password: 'Customer@12345',
    phone: '0912345678',
    role: 'Customer'
  }
];

return recordsToCreate.map((data, index) => ({
  json: {
    index,
    url: baseUrl,
    admin: adminUsers[index % adminUsers.length],
    data
  }
}));

const r = $json;
return [{ json: {
  success: Boolean(r.success),
  admin: r.username,
  targetEmail: r.targetEmail,
  message: r.success ? 'User creation completed and was verified.' : (r.error || 'User creation failed'),
  steps: r.steps || {},
  screenshot: r.screenshot || null,
  runId: r.runId || null
} }];
